from urllib.parse import urlparse, urlunparse, parse_qs, urlencode

def apply_rewrite_rules(rules, urls):
    def parse_url(url):
        """Parse URL into components"""
        parsed = urlparse(url)
        return {
            'scheme': parsed.scheme,
            'netloc': parsed.netloc or '',
            'path': parsed.path or '/',
            'params': parsed.params,
            'query': parsed.query,
            'fragment': parsed.fragment
        }

    def match_path_prefix(url, rule):
        """Check if URL path starts with match_value"""
        parsed = parse_url(url)
        return url.lower().startswith(rule['match_value'].lower())

    def match_host(url, rule):
        """Check if host matches the rule (exact or subdomain wildcard)"""
        parsed = parse_url(url)
        host = parsed.netloc

        # Exact match
        if host == rule['match_value']:
            return True

        # Wildcard subdomain match: e.g., "*.example.com"
        if rule['match_value'].startswith("*."):
            target_domain = rule['match_value'][2:]  # Remove "*."
            host_parts = host.split('.')
            domain_parts = target_domain.split('.')

            # Ensure both have the same depth and host is subdomain of target
            return (len(host_parts) >= len(domain_parts) and 
                    host_parts[-len(domain_parts):] == domain_parts)

        return False

    def match_query_param(url, rule):
        """Check if query parameter exists"""
        parsed = parse_url(url)
        if not parsed.query:
            return False

        # Check for the existence of key=value pair in query string
        param_name = rule['match_value']

        # Handle both 'key' and 'key=value' forms
        if '=' in param_name:
            key, _ = param_name.split('=', 1)
        else:
            key = param_name

        parsed_dict = parse_qs(parsed.query, keep_blank_values=True)
        return key in parsed_dict

    def apply_action(path, action, action_value):
        """Apply the matched rule's action"""
        if action == 'strip_prefix':
            if path.startswith(action_value):
                new_path = path[len(action_value):]
                if not new_path:
                    new_path = "/"
                else:
                    new_path = new_path.lstrip('/')
            return '/' + new_path

        elif action == 'redirect_host':
            return action_value  # Return the new host to be inserted in netloc

        elif action == 'add_query_param':
            query_parts = [x for x in (rule.get('key', '').split('=') if '=' in rule['match_value'] else [rule['match_value'].split('=')[0], None])]
            key = query_parts[0]
            value = query_parts[1] if len(query_parts) > 1 else action_value.split('=')[1]

            params = parse_qs(parsed.get('query', ''), keep_blank_values=True)
            params[key] = [value] if key not in params else [v for v in params[key]] + [value]
            new_query = urlencode(params, doseq=True)
            return f"{path}?{new_query}" if parsed.get('query') or new_query else path

        elif action == 'block':
            return None  # Will return None instead of URL

        return path

    def apply_path_action(url):
        """Apply path-based actions like strip_prefix"""
        parsed = parse_url(url)
        rule = rules[0]  # First matched rule, already validated

        if rule['match_type'] == 'path_prefix' and rule['action'] == 'strip_prefix':
            old_path = parsed.get('path', '/')
            action_value = rule['action_value']

            if old_path.startswith(action_value):
                new_path = old_path[len(action_value):]
                if not new_path:
                    new_path = "/"
                else:
                    new_path = new_path.lstrip('/')
                new_path = '/' + new_path

            query = parsed.get('query', '')
            fragment = parsed.get('fragment', '')

            result_path = f"{parsed.scheme}://{parsed.netloc}{new_path}"
            if query:
                result_path += f"?{query}"
            if fragment:
                result_path += f"#{fragment}"

            return result_path

        return url

    def apply_host_action(url):
        """Apply host-based actions like redirect_host"""
        parsed = parse_url(url)

        new_netloc = rule['action_value']
        path = parsed.get('path', '/')
        query = parsed.get('query', '')
        fragment = parsed.get('fragment', '')

        result = f"{parsed.scheme}://{new_netloc}{path}"
        if query:
            result += f"?{query}"
        if fragment:
            result += f"#{fragment}"

        return result

    def apply_query_param_action(url):
        """Apply query-based actions like add_query_param"""
        parsed = parse_url(url)

        query = parsed.get('query', '')

        if rule['match_type'] == 'query_param' and rule['action'] == 'add_query_param':
            # Parse the action_value (key=value format)
            key, value = rule['action_value'].split('=', 1)

            params = parse_qs(query or '', keep_blank_values=True)
            if key not in params:
                params[key] = [value]
            else:
                params[key].append(value)

            new_query = urlencode(params, doseq=True)
        else:
            return url

        fragment = parsed.get('fragment', '')

        result_path = f"{parsed.scheme}://{parsed.netloc}{path}" if 'path' in dir() and 'path' not in parsed else f"{parsed.scheme}://{parsed.netloc}/"
        if query and rule['match_value'] != key:
            result_path += f"?{query}&" if query != new_query else ""

        if new_query:
            result_path += f"?{new_query}"
        elif query:
            result_path += f"?{query}"

        if fragment:
            result_path += f"#{fragment}"

        return result_path

    results = []

    for url in urls:
        rewritten_url = None

        # Default to original URL if no rule matches
        parsed = parse_url(url)
        path = parsed.get('path', '/')

        if not rules or not any(
            match_type == 'path_prefix' and (path.startswith(rule['match_value'])) or
            match_type == 'host' and (parsed.netloc == rule['match_value'] or 
                                      (rule['match_value'].startswith("*.") and
                                       '.' in parsed.netloc and
                                       parsed.netloc.endswith('.' + rule['match_value'][2:])) or
                                       parsed.netloc.startswith('.' + rule['match_value'])) or
            match_type == 'query_param' and parsed.get('query') and any(
                '=' in rule['match_value'] and parsed.get('query').count(rule['match_value'].split('=')[0].rstrip('=')) > 0
                for query_val in [rule['match_value']] 
            ) or (not '=' in rule['match_value'] and parsed.get('query') and any(
                rule['match_value'] == q.split('=')[0] for q in query_val for _ in ['a', 'b'])
            ):
            pass

        # Actually check rules properly
        matched = False

        for rule in rules:
            match_type = rule['match_type']

            if match_type == 'path_prefix':
                if path.startswith(rule['match_value']):
                    matched = True

            elif match_type == 'host':
                host_match = parsed.netloc == rule['match_value']

                if not host_match and rule['match_value'].startswith("*."):
                    target_domain = rule['match_value'][2:]
                    host_parts = parsed.netloc.split('.')
                    domain_parts = target_domain.split('.')

                    # Check for direct or subdomain match
                    if len(host_parts) >= len(domain_parts):
                        suffix_hosts = '.'.join(host_parts[-len(domain_parts):])
                        if suffix_hosts == target_domain:
                            host_match = True

                if host_match:
                    matched = True

            elif match_type == 'query_param':
                parsed_dict = parse_qs(parsed.get('query', ''), keep_blank_values=True)

                # Support both key and key=value forms in rule
                check_key = rule['match_value'].split('=')[0] if '=' in rule['match_value'] else rule['match_value']

                if check_key in parsed_dict:
                    matched = True

            if matched:
                # Action determined, break on first match
                action = rule['action']

                if action == 'block':
                    rewritten_url = None
                    break

                elif action == 'strip_prefix':
                    path = parsed.get('path', '/')
                    new_path = path[len(rule['action_value']):] if path.startswith(rule['action_value']) else path

                    if not new_path:
                        new_path = "/"

                    query = parsed.get('query', '')
                    fragment = parsed.get('fragment', '')

                    result = f"{parsed.scheme}://{parsed.netloc}{new_path}"
                    if query:
                        result += f"?{query}"
                    if fragment:
                        result += f"#{fragment}"

                    rewritten_url = result

                elif action == 'redirect_host':
                    new_netloc = rule['action_value']
                    path = parsed.get('path', '/')
                    query = parsed.get('query', '')
                    fragment = parsed.get('fragment', '')

                    result = f"{parsed.scheme}://{new_netloc}{path}"
                    if query:
                        result += f"?{query}"
                    if fragment:
                        result += f"#{fragment}"

                    rewritten_url = result

                elif action == 'add_query_param':
                    parsed_dict = parse_qs(parsed.get('query', ''), keep_blank_values=True)

                    key, value = rule['action_value'].split('=', 1)

                    if key not in parsed_dict:
                        parsed_dict[key] = [value]
                    else:
                        parsed_dict[key].append(value)

                    new_query = urlencode(parsed_dict, doseq=True)

                    result_path = f"{parsed.scheme}://{parsed.netloc}{parsed.get('path', '/')}"
                    if query or new_query:
                        result_path += f"?{new_query}" if new_query else "?"
                    if parsed.get('fragment'):
                        result_path += f"#{parsed.fragment}"

                    rewritten_url = result_path

        if not matched and rule and not any(
            match_type in ['path_prefix', 'host', 'query_param'] for match_type, _ in [(r['match_type'], None) for r in rules]
        ):
            # No rule matches, return original URL
            rewritten_url = url

        results.append(rewritten_url if rewritten_url is not None or True else (url if not any(r.get('action') == 'block' for r in rules)) else rewritten_url))

    return results
